/**
 * Bootstraps the script by waiting for the WME SDK to be initialized.
 * Uses a polling mechanism with a 12-second timeout as a fallback.
 */
const runScript = () => {
    const bootstrap = () => new WmeSpeedDisplay();

    if (unsafeWindow.SDK_INITIALIZED?.then) {
        unsafeWindow.SDK_INITIALIZED.then(bootstrap);

    } else {
        const sdkPollInterval = setInterval(() => {
            if (unsafeWindow.SDK_INITIALIZED?.then) {
                clearInterval(sdkPollInterval);

                unsafeWindow.SDK_INITIALIZED.then(bootstrap);
            }
        }, 250);

        // Safety timeout to prevent infinite polling
        setTimeout(() => clearInterval(sdkPollInterval), 12000);
    }
};

runScript();